/**
 * Loads topic-to-skills mapping from the generated JSON file.
 * Called at build time by knowledge topic pages in getStaticProps.
 *
 * The mapping is generated by scripts/generate-topic-skills.mjs from
 * KNOWLEDGE_SKILLS in lib/skills-taxonomy.js, which maps each topic
 * slug to the skill IDs it supports.
 */

import fs from "fs";
import path from "path";

let cachedMapping = null;

/**
 * Returns the skills that support a given knowledge topic.
 * @param {string} topicSlug - e.g., "applied-data-science"
 * @returns {Array<{id: string, label: string}>} - Array of skill objects
 */
export function getSkillsForTopic(topicSlug) {
  if (!cachedMapping) {
    const jsonPath = path.join(process.cwd(), "public/data/topic-skills.json");

    if (!fs.existsSync(jsonPath)) {
      console.warn(`topic-skills.json not found. Run: node scripts/generate-topic-skills.mjs`);
      return [];
    }

    cachedMapping = JSON.parse(fs.readFileSync(jsonPath, "utf-8"));
  }

  return cachedMapping[topicSlug] || [];
}
